1	import type Phaser from 'phaser';
2	import { GameMode, GAME_MODES, type GameModeConfig } from '../types/GameMode';
3	import { getSkorBalance, getCachedSkorBalance, cacheSkorBalance } from '../utils/skor';
4	import BaseScene from './BaseScene';
5	
6	export default class ModeSelectScene extends BaseScene {
7	  private skorText!: Phaser.GameObjects.Text;
8	
9	  constructor() {
10	    super('ModeSelectScene');
11	  }
12	
13	  preload() {
14	    if (!this.textures.exists('background2')) {
15	      this.load.image('background2', 'assets/backgrounds/background2.webp');
16	    }
17	    if (!this.textures.exists('title')) {
18	      this.load.image('title', 'assets/title.webp');
19	    }
20	  }
21	
22	  create() {
23	    super.create();
24	
25	    const background = this.add.image(200, 300, 'background2');
26	    background.setDisplaySize(400, 600);
27	
28	    const title = this.add.image(200, 90, 'title');
29	    title.setScale(0.4);
30	
31	    this.add.text(200, 190, '모드를 선택하세요', {
32	      fontSize: '20px',
33	      color: '#fff',
34	      fontStyle: 'bold',
35	      stroke: '#000',
36	      strokeThickness: 4
37	    }).setOrigin(0.5);
38	
39	    // 클래식 + 대전 모드 버튼 (같은 줄, 캐릭터/랭킹 버튼과 동일 크기)
40	    this.createModeButton(GAME_MODES[0], 120, 250);
41	    this.createBattleButton(280, 250);
42	
43	    // 뽑기 버튼 (SKOR 잔액 포함)
44	    this.createGachaButton(200, 345);
45	
46	    // 하단 버튼 행: 캐릭터 선택 + 랭킹
47	    this.createCharacterButton(120, 435);
48	    this.createLeaderboardButton(280, 435);
49	
50	    // 릴리즈 노트 링크
51	    this.createReleaseNotesLink();
52	
53	    // SKOR 잔액 비동기 로드
54	    this.loadSkorBalance();
55	  }
56	
57	  private async loadSkorBalance() {
58	    try {
59	      const balance = await getSkorBalance();
60	      cacheSkorBalance(balance);
61	      if (this.skorText?.active) {
62	        this.skorText.setText(`💰 ${Math.floor(balance)} SKOR`);
63	      }
64	    } catch {
65	      // 잔액 로드 실패 시 캐시 값 유지
66	    }
67	  }
68	
69	  private createModeButton(modeConfig: GameModeConfig, x: number, y: number) {
70	    const button = this.add.rectangle(x, y, 140, 70, 0xffffff, 1);
71	    button.setStrokeStyle(3, 0x000000);
72	
73	    const titleText = this.add.text(x, y, modeConfig.name, {
74	      fontSize: '18px',
75	      color: '#000',
76	      fontStyle: 'bold'
77	    }).setOrigin(0.5);
78	
79	    button.setInteractive({ useHandCursor: true });
80	    titleText.setInteractive({ useHandCursor: true });
81	
82	    [button, titleText].forEach(element => {
83	      element.on('pointerover', () => button.setFillStyle(0xffff99));
84	      element.on('pointerout',  () => button.setFillStyle(0xffffff));
85	      element.on('pointerdown', () => this.startGame(modeConfig.mode));
86	    });
87	  }
88	
89	  private createBattleButton(x: number, y: number) {
90	    const button = this.add.rectangle(x, y, 140, 70, 0xe74c3c, 1);
91	    button.setStrokeStyle(3, 0xc0392b);
92	
93	    const titleText = this.add.text(x, y, '⚔️ 대전 모드', {
94	      fontSize: '18px',
95	      color: '#ffffff',
96	      fontStyle: 'bold',
97	    }).setOrigin(0.5);
98	
99	    button.setInteractive({ useHandCursor: true });
100	    titleText.setInteractive({ useHandCursor: true });
101	
102	    [button, titleText].forEach(el => {
103	      el.on('pointerover', () => {
104	        button.setFillStyle(0xff6b6b);
105	        button.setStrokeStyle(3, 0xff4444);
106	      });
107	      el.on('pointerout', () => {
108	        button.setFillStyle(0xe74c3c);
109	        button.setStrokeStyle(3, 0xc0392b);
110	      });
111	      el.on('pointerdown', () => {
112	        this.scene.start('BattleMatchScene');
113	      });
114	    });
115	  }
116	
117	  private createGachaButton(x: number, y: number) {
118	    const button = this.add.rectangle(x, y, 300, 75, 0x1a1a2e, 1);
119	    button.setStrokeStyle(3, 0x7b2fff);
120	
121	    // 뽑기 타이틀
122	    this.add.text(x, y - 22, '🎰 캐릭터 뽑기', {
123	      fontSize: '22px',
124	      color: '#ffffff',
125	      fontStyle: 'bold',
126	    }).setOrigin(0.5);
127	
128	    // SKOR 잔액 — 캐시 값 즉시 표시
129	    const cached = getCachedSkorBalance();
130	    const initialSkorLabel = cached !== null ? `💰 ${cached} SKOR` : '💰 -- SKOR';
131	    this.skorText = this.add.text(x, y + 8, initialSkorLabel, {
132	      fontSize: '16px',
133	      color: '#c0a0ff',
134	    }).setOrigin(0.5);
135	
136	    // 비용 안내
137	    this.add.text(x, y + 28, '1회 100 · 10회 900', {
138	      fontSize: '12px',
139	      color: '#888888',
140	    }).setOrigin(0.5);
141	
142	    button.setInteractive({ useHandCursor: true });
143	
144	    button.on('pointerover', () => {
145	      button.setFillStyle(0x2d1a5e);
146	      button.setStrokeStyle(3, 0xaa66ff);
147	    });
148	    button.on('pointerout', () => {
149	      button.setFillStyle(0x1a1a2e);
150	      button.setStrokeStyle(3, 0x7b2fff);
151	    });
152	    button.on('pointerdown', () => {
153	      this.scene.start('GachaScene');
154	    });
155	  }
156	
157	  private createCharacterButton(x: number, y: number) {
158	    const button = this.add.rectangle(x, y, 140, 70, 0x2a2a2a, 1);
159	    button.setStrokeStyle(2, 0x888888);
160	
161	    this.add.text(x, y, '🧬 캐릭터', {
162	      fontSize: '18px',
163	      color: '#ffffff',
164	      fontStyle: 'bold',
165	    }).setOrigin(0.5);
166	
167	    button.setInteractive({ useHandCursor: true });
168	
169	    button.on('pointerover', () => button.setFillStyle(0x444444));
170	    button.on('pointerout',  () => button.setFillStyle(0x2a2a2a));
171	    button.on('pointerdown', () => {
172	      this.scene.start('CharacterSelectScene');
173	    });
174	  }
175	
176	  private createLeaderboardButton(x: number, y: number) {
177	    const button = this.add.rectangle(x, y, 140, 70, 0x4a90e2, 1);
178	    button.setStrokeStyle(2, 0x2e5c8a);
179	
180	    this.add.text(x, y, '🏆 랭킹', {
181	      fontSize: '18px',
182	      color: '#fff',
183	      fontStyle: 'bold',
184	    }).setOrigin(0.5);
185	
186	    button.setInteractive({ useHandCursor: true });
187	
188	    button.on('pointerover', () => button.setFillStyle(0x5ba3f5));
189	    button.on('pointerout',  () => button.setFillStyle(0x4a90e2));
190	    button.on('pointerdown', () => {
191	      this.scene.start('LeaderboardScene');
192	    });
193	  }
194	
195	  private createReleaseNotesLink() {
196	    const text = this.add.text(200, 520, '📋 릴리즈 노트', {
197	      fontSize: '15px',
198	      color: '#cccccc',
199	      stroke: '#000',
200	      strokeThickness: 3,
201	    }).setOrigin(0.5);
202	
203	    text.setInteractive({ useHandCursor: true });
204	    text.on('pointerover', () => text.setColor('#FFD700'));
205	    text.on('pointerout',  () => text.setColor('#cccccc'));
206	    text.on('pointerdown', () => this.scene.start('ReleaseNotesScene'));
207	  }
208	
209	  private startGame(mode: GameMode) {
210	    if (mode === GameMode.CLASSIC) {
