// 게임 인스턴스는 동기적으로 즉시 생성 (키보드 입력 정상 동작 보장)
const game = new Phaser.Game(config);

// 저장된 뮤트 설정 복원
game.events.once('ready', () => {
  if (isBgmMuted()) game.sound.mute = true;

  // 모바일 합성 mouse 이벤트 전역 차단
  // touchstart 후 브라우저가 생성하는 mousedown이 Phaser에 이중으로 전달되는 문제 수정
  // capture: true로 Phaser보다 먼저 가로채고, 350ms 이내 mousedown은 무시
  let lastTouchTime = 0;
  const canvas = game.canvas;

  canvas.addEventListener('touchstart', () => {
    lastTouchTime = performance.now();
  }, { passive: true });

  canvas.addEventListener('mousedown', (e) => {
    if (performance.now() - lastTouchTime < 350) {
      e.stopImmediatePropagation();
      e.preventDefault();
    }
  }, true);
});

